import random
import time
from functools import wraps, partial


def do_avg_time(times, func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        for i in range(times):
            func(*args, **kwargs)
        print(f&quot;函数{func.__name__}平均运行时间：{(time.time() - start)&#47;times:.2f}s&quot;)
    return wrapper

def avg_time(times=1):
    # partial传递股东参数是位置参数，会放在最前面
    return partial(do_avg_time, times)

